// ──────────────────────────────────────────
// XOP 音声入力 正規化ノード
// Whisper の誤認識パターンを修正する
// ──────────────────────────────────────────
const item = $input.first().json;
let text = item.question || '';

// 1. 製品・技術用語
text = text.replace(/ゾップ|ゾッポ|ExOP|X\.O\.P/gi, 'XOP');
text = text.replace(/プロテア(?!ケア)|プロテカ|プロテーケア|プロテラ/g, 'プロテケア');
text = text.replace(/ウォーターセラミックス|水セラミック/g, 'ウォーターセラミック');
text = text.replace(/クラック(?!ス)|クラクス/g, 'クラックス');

// 2. 人名
text = text.replace(/湯沢/g, '湯澤');
text = text.replace(/稲沢/g, '稲澤');
text = text.replace(/中沢/g, '中澤');
text = text.replace(/笹木/g, '佐々木');

// 3. 会社名
text = text.replace(/パナホーム(?!リフォーム)/g, 'Panaホームリフォーム');
text = text.replace(/アルティス/g, 'Artis');

return {
  ...item,
  question: text,
  _normalized: text !== item.question
};

// Wiki + Deals + Tasks を合体してGeminiプロンプトを作る

const question = $('🔤 テキスト正規化').first().json.question;
const chatId   = $('🔤 テキスト正規化').first().json.chatId;
const username = $('🔤 テキスト正規化').first().json.username;

// ── 1. Wiki コンテンツ ──
const wikiData = $('📚 Wiki取得 (GAS)').first().json;
const wikiContent = wikiData.success ? wikiData.content : '(Wiki取得失敗)';

// ── 2. Deals (案件) フォーマット ──
const dealsData = $('💼 Deals取得 (NocoDB)').first().json;
let dealsText = '## 現在の案件パイプライン\n';
if (dealsData.list && dealsData.list.length > 0) {
  dealsData.list.forEach(deal => {
    const fields = Object.entries(deal)
      .filter(([k]) => !k.startsWith('nc_') && k !== 'Id' && deal[k])
      .map(([k, v]) => `  ${k}: ${v}`)
      .join('\n');
    dealsText += `\n### 案件ID: ${deal.Id}\n${fields}\n`;
  });
  dealsText += `\n合計 ${dealsData.list.length} 件（完了除く）`;
} else {
  dealsText += '現在アクティブな案件なし';
}

// ── 3. Tasks フォーマット ──
const tasksData = $('✅ Tasks取得 (NocoDB)').first().json;
let tasksText = '## 未完了タスク一覧\n';
if (tasksData.list && tasksData.list.length > 0) {
  tasksData.list.forEach(task => {
    const fields = Object.entries(task)
      .filter(([k]) => !k.startsWith('nc_') && k !== 'Id' && task[k])
      .map(([k, v]) => `  ${k}: ${v}`)
      .join('\n');
    tasksText += `\n### タスクID: ${task.Id}\n${fields}\n`;
  });
  tasksText += `\n合計 ${tasksData.list.length} 件（Done除く）`;
} else {
  tasksText += '未完了タスクなし';
}

// ── 4. System Prompt 組み立て ──
const systemPrompt = `あなたはプロテケアXOP（株式会社クラックス）の社内AIアシスタントです。
以下の情報源を使って、質問に日本語で答えてください。

【ルール】
- 数字（価格・スペック・日付）は正確に引用する
- 情報がない場合は「記録にありません。詳細は宮脇さんへご確認ください」と答える
- 回答は簡潔に（最大500文字）。箇条書きで整理する
- 内部文書なので社外秘データもそのまま回答してよい

【音声誤認識の補正】
"ゾップ"→"XOP"、"プロテカ"→"プロテケア"、"クラック"→"クラックス" などの誤認識を自動補正して解釈すること。

━━━━━━━━━━━━━━━━━━━━━━━━
【情報源1: XOP製品・戦略Wiki】
${wikiContent}

━━━━━━━━━━━━━━━━━━━━━━━━
【情報源2: 案件パイプライン（リアルタイム）】
${dealsText}

━━━━━━━━━━━━━━━━━━━━━━━━
【情報源3: タスク管理（リアルタイム）】
${tasksText}`;

const userMessage = `【質問者】${username}\n【質問】${question}`;

return {
  chatId,
  question,
  username,
  systemPrompt,
  userMessage,
  wikiFileCount: wikiData.fileCount || 0,
  dealsCount: dealsData.list?.length || 0,
  tasksCount: tasksData.list?.length || 0
};

const response = $input.first().json;
// Gemini レスポンス形式: candidates[0].content.parts[0].text
const answer = response.candidates?.[0]?.content?.parts?.[0]?.text
  || 'エラー: 回答を取得できませんでした';

const chatId       = $('🧩 プロンプト構築 (Wiki+DB)').first().json.chatId;
const wikiCount    = $('🧩 プロンプト構築 (Wiki+DB)').first().json.wikiFileCount;
const dealsCount   = $('🧩 プロンプト構築 (Wiki+DB)').first().json.dealsCount;
const tasksCount   = $('🧩 プロンプト構築 (Wiki+DB)').first().json.tasksCount;

const footer = `\n\n_参照: Wiki${wikiCount}件 / 案件${dealsCount}件 / タスク${tasksCount}件_`;
const text = `💡 *XOP Bot*\n\n${answer}${footer}`;

return { chatId, text };
